import{az as o,P as l,Q as a,aQ as i}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/服务端/双token.md","filePath":"面试题/服务端/双token.md","lastUpdated":1782478366000}'),n={name:"面试题/服务端/双token.md"};function t(s,e,r,k,c,T){return l(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="双-token-方案-accesstoken-refreshtoken" tabindex="-1">双 Token 方案（AccessToken + RefreshToken） <a class="header-anchor" href="#双-token-方案-accesstoken-refreshtoken" aria-label="Permalink to “双 Token 方案（AccessToken + RefreshToken）”">​</a></h2><p>是一套登录刷新机制，和 token 是什么格式无关，解决单 token 过期矛盾：</p><h3 id="分工" tabindex="-1">分工 <a class="header-anchor" href="#分工" aria-label="Permalink to “分工”">​</a></h3><ol><li>AccessToken（访问令牌）</li></ol><ul><li>短期有效：5~30 分钟；</li><li>所有业务接口请求头携带，用来鉴权；</li><li>泄露影响窗口短，风险低。</li></ul><ol start="2"><li>RefreshToken（刷新令牌）</li></ol><ul><li>长期有效：7~30 天；</li><li>不参与业务请求，只用来调用 /refresh 接口换新 AccessToken；</li><li>通常存在后端 Redis / 数据库，支持主动失效（登出、改密码、踢设备）。</li></ul><h2 id="jwt-双-token-方案-生产级标准" tabindex="-1">JWT 双 Token 方案（生产级标准） <a class="header-anchor" href="#jwt-双-token-方案-生产级标准" aria-label="Permalink to “JWT 双 Token 方案（生产级标准）”">​</a></h2><ol><li>用户登录成功，服务端用密钥签发 Access Token + Refresh Token，令牌本身携带用户 ID、角色等信息；</li><li>前端将令牌存入 localStorage / Cookie / 移动端本地存储；</li><li>后续业务请求，前端手动在 <code>Authorization: Bearer &lt;token&gt;</code> 请求头中携带 Access Token；</li><li>服务端收到请求，用密钥验签，确认未篡改、未过期后，直接从令牌中读取用户信息，无需查库；</li><li>登出 / 踢下线：将令牌 jti 写入 Redis 黑名单，校验时多一步黑名单检查。</li></ol><h2 id="常见误区澄清" tabindex="-1">常见误区澄清 <a class="header-anchor" href="#常见误区澄清" aria-label="Permalink to “常见误区澄清”">​</a></h2><ol><li><p>误区 1：双 Token 就是两个 JWT</p><p>错。RefreshToken 完全可以不用 JWT： Refresh 只做刷新凭证，不需要携带用户信息，后端只需要存它的有效状态，用 UUID 随机字符串更轻量，注销直接删 Redis 即可，比 JWT 更容易管控。</p></li><li><p>误区 2：JWT 就是双 Token</p><p>错。绝大多数简单后台、H5 项目只用单个 JWT，不存在双 Token 机制。</p></li><li><p>误区 3：不用 JWT 就不能做双 Token</p><p>错。前后端可以用普通随机字符串作为 AccessToken+RefreshToken，全部存在 Redis，一样是双 Token 体系，只是失去 JWT 无状态、自携带信息的优势。</p></li></ol>',11)])])}const f=o(n,[["render",t]]);export{p as __pageData,f as default};
